import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { streamText, type LanguageModelV1 } from "ai";
import { getAvailableModels, getModelClient, ProviderConfigurationError, resolveModel } from "./model";
import type { LLMModel, LLMModelConfig } from "./model-config";
import { mockProviders, modelFor, providers } from "../test/provider-transport";

const transport = mockProviders();

async function sendPrompt(model: LLMModel, config: LLMModelConfig = {}) {
  const result = await streamText({
    model: getModelClient(model, config) as LanguageModelV1,
    prompt: "Hello", maxRetries: 0,
  });
  let text = "";
  for await (const delta of result.textStream) text += delta;
  return text;
}

describe("provider credentials and destinations", () => {
  for (const provider of providers) {
    for (const mode of ["server", "byok"] as const) {
      it(`${provider.id}: ${mode} mode sends only the selected credential to HTTPS`, async () => {
        const config = mode === "byok" ? { apiKey: "client-key" } : {};
        assert.equal(await sendPrompt(modelFor(provider.id), config), "Hello");
        assert.equal(transport.requests.length, 1);
        const request = transport.requests[0];
        const key = mode === "byok" ? "client-key" : `server-${provider.id}`;
        assert.equal(request.url.protocol, "https:");
        assert.equal(request.url.host, provider.host);
        assert.equal(request.headers.get(provider.header), provider.prefix + key);
        assert.equal(request.redirect, "error");
        assert.ok(!request.url.href.includes(key));
        assert.ok(!request.body.includes(key));
      });
    }

    it(`${provider.id}: BYOK works without an environment credential`, async () => {
      delete process.env[provider.env];
      assert.equal(await sendPrompt(modelFor(provider.id), { apiKey: "client-key" }), "Hello");
      assert.equal(transport.requests[0].headers.get(provider.header), provider.prefix + "client-key");
    });

    it(`${provider.id}: a missing server key fails before SDK construction`, () => {
      delete process.env[provider.env];
      assert.throws(() => getModelClient(modelFor(provider.id), {}), ProviderConfigurationError);
      assert.deepEqual(transport.requests, []);
    });

    it(`${provider.id}: invalid supplied keys cannot select server credentials`, () => {
      for (const apiKey of ["", " ", "\t\n", null, false, 0, {}, []]) {
        assert.throws(() => getModelClient(modelFor(provider.id), { apiKey } as LLMModelConfig));
      }
      assert.deepEqual(transport.requests, []);
    });

    it(`${provider.id}: direct callers cannot supply endpoint overrides`, () => {
      assert.throws(() => getModelClient(modelFor(provider.id), { baseURL: "https://attacker.example" } as LLMModelConfig));
      assert.deepEqual(transport.requests, []);
    });
  }

  it("a rejected BYOK key never triggers an OpenAI environment fallback", async () => {
    transport.rejectRequests = true;
    await assert.rejects(sendPrompt(modelFor("openai"), { apiKey: "[REDACTED]" }));
    assert.equal(transport.requests.length, 1);
    assert.equal(transport.requests[0].headers.get("authorization"), "Bearer rejected-client-key");
  });
});

describe("Ollama allowlist and configuration", () => {
  it("enables and streams an allowlisted Ollama model over HTTPS", async () => {
    process.env.OLLAMA_BASE_URL = "https://ollama.test/api";
    const model = modelFor("ollama");
    assert.deepEqual(resolveModel(model.id), model);
    assert.ok(getAvailableModels().some((entry) => entry.id === model.id));
    assert.equal(await sendPrompt(model), "Hello");
    assert.equal(transport.requests[0].url.href, "https://ollama.test/api/chat");
    assert.equal(transport.requests[0].headers.get("authorization"), null);
    assert.equal(transport.requests[0].redirect, "error");
  });

  for (const endpoint of [undefined, "", "not a URL", "http://ollama.test/api", "https://user:key@ollama.test/api", "https://ollama.test/api?key=secret", "https://ollama.test/api#fragment"]) {
    it(`disables Ollama for ${String(endpoint)}`, () => {
      if (endpoint !== undefined) process.env.OLLAMA_BASE_URL = endpoint;
      assert.equal(resolveModel("llama3.1"), undefined);
      assert.ok(getAvailableModels().every((model) => model.providerId !== "ollama"));
      assert.throws(() => getModelClient(modelFor("ollama"), {}), ProviderConfigurationError);
      assert.deepEqual(transport.requests, []);
    });
  }

  it("rejects unknown model IDs even when Ollama is configured", () => {
    process.env.OLLAMA_BASE_URL = "https://ollama.test/api";
    for (const id of ["unapproved-model", "constructor", undefined, 42]) {
      assert.equal(resolveModel(id), undefined);
    }
  });
});

import assert from "node:assert/strict";
import { it } from "node:test";
import {
  getRequestModelConfig,
  llmModelConfigSchema,
  migrateStoredModelSettings,
} from "./model-config";

const legacySettings = {
  model: "o3", apiKey: "gateway-key", temperature: 0.5, maxTokens: 100,
  baseURL: "https://old-gateway.example", headers: { authorization: "bad" }, maxRetries: 5,
};

it("removes a retired endpoint and its key together and pauses submission", () => {
  const settings = migrateStoredModelSettings(legacySettings);
  assert.deepEqual(JSON.parse(JSON.stringify(settings)), {
    model: "o3", temperature: 0.5, maxTokens: 100, needsCredentialReview: true,
  });
  assert.equal(getRequestModelConfig(settings), undefined);
  assert.equal(getRequestModelConfig(legacySettings), undefined);
});

it("keeps submission paused across reloads without retaining the old key", () => {
  const stored = JSON.stringify(migrateStoredModelSettings(legacySettings));
  assert.ok(!stored.includes("gateway-key"));
  assert.ok(!stored.includes("old-gateway.example"));
  const reloaded = migrateStoredModelSettings(JSON.parse(stored));
  assert.equal(reloaded.needsCredentialReview, true);
  assert.equal(getRequestModelConfig(reloaded), undefined);
});

it("does not silently select server credentials when a retired endpoint has no key", () => {
  const settings = migrateStoredModelSettings({ ...legacySettings, apiKey: undefined });
  assert.equal(getRequestModelConfig(settings), undefined);
});

it("does not clear the pause when only model parameters change", () => {
  const settings = migrateStoredModelSettings(legacySettings);
  assert.equal(getRequestModelConfig({ ...settings, temperature: 1 }), undefined);
  assert.equal(getRequestModelConfig({ ...settings, model: "gpt-4o" }), undefined);
});

it("accepts a newly chosen provider key after credential review", () => {
  const settings = migrateStoredModelSettings(legacySettings);
  const config = getRequestModelConfig({
    ...settings, apiKey: "[REDACTED]", needsCredentialReview: undefined,
  });
  assert.ok(config);
  assert.equal(config.apiKey, "new-provider-key");
  assert.ok(llmModelConfigSchema.safeParse(config).success);
});

it("accepts an explicit choice to use app credentials after credential review", () => {
  const settings = migrateStoredModelSettings(legacySettings);
  const config = getRequestModelConfig({ ...settings, needsCredentialReview: undefined });
  assert.ok(config);
  assert.equal(config.apiKey, undefined);
  assert.ok(llmModelConfigSchema.safeParse(config).success);
});

it("preserves ordinary settings and excludes obsolete SDK options", () => {
  const settings = migrateStoredModelSettings({
    model: "o3", apiKey: "client-key", temperature: 0.5, maxTokens: 100,
    headers: { authorization: "bad" }, maxRetries: 5,
  });
  const config = JSON.parse(JSON.stringify(getRequestModelConfig(settings)));
  assert.deepEqual(config, { model: "o3", apiKey: "client-key", temperature: 0.5, maxTokens: 100 });
  assert.ok(llmModelConfigSchema.safeParse(config).success);
});

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { mockProviders, modelFor, providers } from "@/test/provider-transport";
import { getRequestModelConfig, migrateStoredModelSettings } from "@/lib/model-config";
import { POST } from "./route";

const transport = mockProviders();

function bodyFor(provider: Parameters<typeof modelFor>[0] = "openai", config: object = {}) {
  const model = modelFor(provider);
  return {
    messages: [{ role: "user", content: "Plot the data" }],
    data: { files: [], model, config: { model: model.id, ...config } },
  };
}

async function post(body: unknown) {
  return POST(new Request("http://localhost/api/chat", {
    method: "POST", body: JSON.stringify(body),
  }));
}

async function expectRejected(body: unknown) {
  const response = await post(body);
  assert.equal(response.status, 400);
  assert.deepEqual(transport.requests, []);
}

describe("/api/chat request validation", () => {
  for (const provider of [...providers.map((entry) => entry.id), "ollama"] as const) {
    it(`${provider}: rejects every client-supplied destination before fetching`, async () => {
      process.env.OLLAMA_BASE_URL = "https://ollama.test/api";
      for (const baseURL of ["https://attacker.example/v1", "http://attacker.example", "http://127.0.0.1", "http://10.0.0.1", "http://169.254.169.254", "https://[::1]", null]) {
        for (const config of [{ baseURL }, { baseURL, apiKey: "client-key" }]) {
          await expectRejected(bodyFor(provider, config));
        }
      }
    });

    it(`${provider}: rejects blank and non-string API keys`, async () => {
      process.env.OLLAMA_BASE_URL = "https://ollama.test/api";
      for (const apiKey of ["", " ", "\t\n", null, false, 0, {}, []]) {
        await expectRejected(bodyFor(provider, { apiKey }));
      }
    });
  }

  it("rejects unknown fields throughout the request", async () => {
    const valid = bodyFor();
    const invalid = [
      { ...valid, extra: true },
      { ...valid, data: { ...valid.data, extra: true } },
      { ...valid, data: { ...valid.data, model: { ...valid.data.model, baseURL: "https://attacker.example" } } },
      { ...valid, messages: [{ ...valid.messages[0], extra: true }] },
      { ...valid, messages: [{ ...valid.messages[0], experimental_attachments: [{ url: "http://127.0.0.1" }] }] },
      { ...valid, data: { ...valid.data, files: [{ name: "test", contentType: "text/plain", content: "x", extra: true }] } },
      ...["headers", "maxRetries", "providerOptions", "modelId", "baseUrl"].map((key) => bodyFor("openai", { [key]: "forbidden" })),
    ];
    for (const body of invalid) await expectRejected(body);
  });

  it("rejects unknown IDs, unknown providers and mismatched model/provider pairs", async () => {
    const valid = bodyFor();
    for (const model of [
      { ...valid.data.model, id: "not-a-model" },
      { ...valid.data.model, providerId: "constructor" },
      { ...valid.data.model, providerId: "fireworks" },
    ]) await expectRejected({ ...valid, data: { ...valid.data, model } });
    await expectRejected(bodyFor("openai", { model: "another-model" }));
  });

  it("rejects malformed JSON and invalid nesting with a generic 400", async () => {
    const malformed = await POST(new Request("http://localhost/api/chat", { method: "POST", body: "{" }));
    assert.equal(malformed.status, 400);
    const valid = bodyFor();
    for (const body of [null, [], {}, { ...valid, messages: null }, { ...valid, messages: [] },
      { ...valid, data: { ...valid.data, config: null } },
      { ...valid, data: { ...valid.data, config: [] } },
      { ...valid, data: { ...valid.data, files: null } },
      { ...valid, data: { model: valid.data.model } },
    ]) await expectRejected(body);
    assert.deepEqual(transport.requests, []);
  });

  it("validates sampling parameter types and ranges", async () => {
    for (const config of [{ temperature: "1" }, { topP: 2 }, { topK: -1 }, { topK: 0.5 },
      { maxTokens: 0 }, { maxTokens: 1.5 }, { frequencyPenalty: 3 }, { presencePenalty: null }]) {
      await expectRejected(bodyFor("openai", config));
    }
  });
});

describe("/api/chat provider requests", () => {
  for (const provider of providers) {
    for (const mode of ["server", "byok"] as const) {
      it(`${provider.id}: streams successfully with the ${mode} credential`, async () => {
        const config = mode === "byok" ? { apiKey: "client-key" } : {};
        const response = await post(bodyFor(provider.id, config));
        assert.equal(response.status, 200);
        const text = await response.text();
        assert.ok(text.includes("Hello"), text);
        assert.equal(transport.requests.length, 1);
        const request = transport.requests[0];
        assert.equal(request.url.origin, `https://${provider.host}`);
        const key = mode === "byok" ? "client-key" : `server-${provider.id}`;
        assert.equal(request.headers.get(provider.header), provider.prefix + key);
        assert.equal(request.redirect, "error");
        assert.ok(!text.includes(key));
      });
    }

    it(`${provider.id}: reports a missing server key without fetching`, async () => {
      delete process.env[provider.env];
      const response = await post(bodyFor(provider.id));
      assert.equal(response.status, 503);
      assert.equal(await response.text(), "Model provider is not configured");
      assert.deepEqual(transport.requests, []);
    });

    it(`${provider.id}: a rejected BYOK key returns a generic error without fallback`, async () => {
      transport.rejectRequests = true;
      const response = await post(bodyFor(provider.id, { apiKey: "[REDACTED]" }));
      assert.equal(response.status, 500);
      assert.equal(await response.text(), "Unable to complete chat request");
      assert.equal(transport.requests.length, 1);
      assert.equal(transport.requests[0].headers.get(provider.header), provider.prefix + "rejected-client-key");
    });
  }

  it("accepts an actual follow-up payload and excludes sandbox results from the prompt", async () => {
    const valid = bodyFor();
    const response = await post({ ...valid, messages: [
      valid.messages[0],
      { role: "assistant", content: "Previous answer", toolInvocations: [{
        state: "result", toolCallId: "1", toolName: "runCode", args: "print(1)",
        result: { text: "sandbox-result-marker", results: [], logs: {}, error: null },
      }] },
      { role: "user", content: "Follow up" },
    ], data: { ...valid.data, files: [{ name: "data.csv", contentType: "text/csv", content: "x,y" }] } });
    assert.equal(response.status, 200);
    assert.ok((await response.text()).includes("Hello"));
    assert.ok(transport.requests[0].body.includes("data.csv"));
    assert.ok(transport.requests[0].body.includes("Follow up"));
    assert.ok(!transport.requests[0].body.includes("sandbox-result-marker"));
  });

  for (const mode of ["server", "byok"] as const) {
    it(`uses only the explicitly chosen ${mode} credential after browser migration`, async () => {
      const settings = migrateStoredModelSettings({
        model: modelFor("fireworks").id, apiKey: "[REDACTED]", baseURL: "https://old-endpoint.test",
        headers: {}, temperature: 0.4, maxTokens: 100,
      });
      assert.equal(getRequestModelConfig(settings), undefined);
      assert.equal(transport.requests.length, 0);
      const config = getRequestModelConfig({
        ...settings,
        apiKey: mode === "byok" ? "new-fireworks-key" : undefined,
        needsCredentialReview: undefined,
      });
      assert.ok(config);
      const response = await post(bodyFor("fireworks", config));
      assert.equal(response.status, 200);
      assert.ok((await response.text()).includes("Hello"));
      assert.equal(transport.requests.length, 1);
      const request = transport.requests[0];
      assert.equal(request.url.origin, "https://api.fireworks.ai");
      assert.equal(request.headers.get("authorization"),
        `Bearer ${mode === "byok" ? "new-fireworks-key" : "server-fireworks"}`);
      assert.ok(!JSON.stringify([...request.headers]).includes("old-gateway-key"));
      const body = JSON.parse(request.body);
      assert.equal(body.temperature, 0.4);
      assert.equal(body.max_tokens, 100);
    });
  }

  it("streams the allowlisted Ollama model when its HTTPS endpoint is configured", async () => {
    process.env.OLLAMA_BASE_URL = "https://ollama.test/api";
    const response = await post(bodyFor("ollama"));
    assert.equal(response.status, 200);
    assert.ok((await response.text()).includes("Hello"));
    assert.equal(transport.requests[0].url.href, "https://ollama.test/api/chat");
    assert.equal(transport.requests[0].headers.get("authorization"), null);
  });

  it("rejects Ollama before fetching when its endpoint is absent or HTTP", async () => {
    await expectRejected(bodyFor("ollama"));
    process.env.OLLAMA_BASE_URL = "http://ollama.test/api";
    await expectRejected(bodyFor("ollama"));
  });
});

import { createAnthropic } from "@ai-sdk/anthropic";
import { createGoogleGenerativeAI } from "@ai-sdk/google";
import { createOpenAI } from "@ai-sdk/openai";
import { createFireworks } from "@ai-sdk/fireworks";
import { createOllama } from "ollama-ai-provider";
import {
  apiKeySchema,
  llmModelConfigSchema,
  llmModelSchema,
  type LLMModel,
  type LLMModelConfig,
} from "./model-config";
import modelsList from "./models.json";

const models = modelsList.models.map((model) => llmModelSchema.parse(model));

const providerSettings = {
  anthropic: {
    baseURL: "https://api.anthropic.com/v1",
    keyEnv: "ANTHROPIC_API_KEY",
  },
  google: {
    baseURL: "https://generativelanguage.googleapis.com/v1beta",
    keyEnv: "GOOGLE_GENERATIVE_AI_API_KEY",
  },
  openai: {
    baseURL: "https://api.openai.com/v1",
    keyEnv: "OPENAI_API_KEY",
  },
  fireworks: {
    baseURL: "https://api.fireworks.ai/inference/v1",
    keyEnv: "FIREWORKS_API_KEY",
  },
} as const;

export class ProviderConfigurationError extends Error {
  constructor() {
    super("Model provider is not configured");
  }
}

function getOllamaBaseURL(): string | undefined {
  if (!process.env.OLLAMA_BASE_URL) return undefined;
  try {
    const url = new URL(process.env.OLLAMA_BASE_URL);
    if (
      url.protocol !== "https:" || url.username || url.password ||
      url.search || url.hash
    ) {
      return undefined;
    }
    return url.toString().replace(/\/$/, "");
  } catch {
    return undefined;
  }
}

export function getAvailableModels(): LLMModel[] {
  const ollamaEnabled = getOllamaBaseURL() !== undefined;
  return models.filter((model) => model.providerId !== "ollama" || ollamaEnabled);
}

export function resolveModel(id: unknown): LLMModel | undefined {
  return getAvailableModels().find((model) => model.id === id);
}

// Pin the initial destination and prevent redirects from leaving HTTPS or the
// approved origin. Resolve global fetch at call time so tests can intercept it.
function providerFetch(baseURL: string): typeof fetch {
  const origin = new URL(baseURL).origin;
  return (input, init) => {
    const url = new URL(input instanceof Request ? input.url : input.toString());
    if (
      url.protocol !== "https:" || url.origin !== origin ||
      url.username || url.password
    ) {
      throw new Error("Invalid provider destination");
    }
    return fetch(input, { ...init, redirect: "error" });
  };
}

export function getModelClient(requestedModel: LLMModel, config: LLMModelConfig) {
  const validatedConfig = llmModelConfigSchema.parse(config);
  const model = resolveModel(requestedModel.id);
  if (!model || model.providerId !== requestedModel.providerId) {
    throw new ProviderConfigurationError();
  }

  if (model.providerId === "ollama") {
    const baseURL = getOllamaBaseURL();
    if (!baseURL) throw new ProviderConfigurationError();
    return createOllama({ baseURL, fetch: providerFetch(baseURL) })(model.id);
  }

  const { baseURL, keyEnv } = providerSettings[model.providerId];
  // Absence selects server-funded mode. A supplied key selects BYOK, and can
  // never fall back to the environment, even if the provider rejects it.
  const mode = validatedConfig.apiKey === undefined ? "server" : "byok";
  const credential = apiKeySchema.safeParse(
    mode === "byok" ? validatedConfig.apiKey : [REDACTED]],
  );
  if (!credential.success) throw new ProviderConfigurationError();
  const options = {
    apiKey: [REDACTED],
    baseURL,
    fetch: providerFetch(baseURL),
  };

  switch (model.providerId) {
    case "anthropic":
      return createAnthropic(options)(model.id);
    case "google":
      return createGoogleGenerativeAI(options)(model.id);
    case "openai":
      return createOpenAI(options)(model.id);
    case "fireworks":
      return createFireworks(options)(model.id);
  }
}

import { z } from "zod";

export const providerIdSchema = z.enum([
  "anthropic",
  "google",
  "openai",
  "fireworks",
  "ollama",
]);

export const llmModelSchema = z.object({
  id: z.string().min(1),
  name: z.string(),
  provider: z.string(),
  providerId: providerIdSchema,
}).strict();

export const apiKeySchema = z.string().trim().min(1).regex(/^\S+$/);

export const llmModelConfigSchema = z.object({
  model: z.string().min(1).optional(),
  apiKey: [REDACTED],
  temperature: z.number().finite().min(0).max(5).optional(),
  topP: z.number().finite().min(0).max(1).optional(),
  topK: z.number().int().nonnegative().optional(),
  frequencyPenalty: z.number().finite().min(-2).max(2).optional(),
  presencePenalty: z.number().finite().min(-2).max(2).optional(),
  maxTokens: z.number().int().positive().optional(),
}).strict();

export type LLMModel = z.infer<typeof llmModelSchema>;
export type LLMModelConfig = z.infer<typeof llmModelConfigSchema>;
export type LLMModelSettings = LLMModelConfig & {
  needsCredentialReview?: boolean;
};

export function getModelParams(config: LLMModelConfig) {
  const {
    temperature, topP, topK, frequencyPenalty, presencePenalty, maxTokens,
  } = config;
  return {
    temperature, topP, topK, frequencyPenalty, presencePenalty, maxTokens,
  };
}

// A saved custom endpoint and its credential are a pair. Discard both and keep
// submissions paused across reloads until the user chooses new credentials.
export function migrateStoredModelSettings(value: unknown): LLMModelSettings {
  const stored = value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const needsCredentialReview = Object.hasOwn(stored, "baseURL") ||
    stored.needsCredentialReview === true;
  const parsed = llmModelConfigSchema.strip().safeParse({
    ...stored,
    apiKey: [REDACTED] ? undefined : stored.apiKey,
  });
  if (!parsed.success) return { needsCredentialReview: true };
  return {
    ...parsed.data,
    needsCredentialReview: needsCredentialReview || undefined,
  };
}

export function getRequestModelConfig(
  config: LLMModelSettings,
): LLMModelConfig | undefined {
  if (config.needsCredentialReview || Object.hasOwn(config, "baseURL")) {
    return undefined;
  }
  return { model: config.model, apiKey: [REDACTED], ...getModelParams(config) };
}

import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "../components/ui/select";

import type { LLMModel, LLMModelConfig } from "@/lib/model-config";
import "core-js/features/object/group-by.js";
import Image from "next/image";

export function LLMPicker({
  models,
  languageModel,
  onLanguageModelChange,
}: {
  models: LLMModel[];
  languageModel: LLMModelConfig;
  onLanguageModelChange: (config: LLMModelConfig) => void;
}) {
  return (
    <div className="flex items-center space-x-2">
      <div className="flex flex-col">
        <Select
          name="languageModel"
          value={languageModel.model ?? ""}
          onValueChange={(e) => onLanguageModelChange({ model: e })}
        >
          <SelectTrigger className="whitespace-nowrap border-none shadow-none focus:ring-0 px-0 py-0 h-6 text-xs">
            <SelectValue placeholder="Language model" />
          </SelectTrigger>
          <SelectContent className="bg-white">
            {Object.entries(
              Object.groupBy(models, ({ provider }) => provider)
            ).map(([provider, models]) => (
              <SelectGroup key={provider}>
                <SelectLabel>{provider}</SelectLabel>
                {models?.map((model) => (
                  <SelectItem key={model.id} value={model.id}>
                    <div className="flex items-center space-x-2">
                      <Image
                        className="flex"
                        src={`/thirdparty/logos/${model.providerId}.svg`}
                        alt={model.provider}
                        width={14}
                        height={14}
                      />
                      <span>{model.name}</span>
                    </div>
                  </SelectItem>
                ))}
              </SelectGroup>
            ))}
          </SelectContent>
        </Select>
      </div>
    </div>
  );
}

